@bp.delete("/invoices/<invoice_id>")
def delete_invoice(invoice_id):
    invoice = _INVOICES.get(invoice_id)
    if invoice is None:
        return errors.problem(404, "Invoice not found")
    # Finalized invoices are posted to the ledger and fall under the
    # retention policy, so only drafts may be deleted.
    if invoice.ledger_ref:
        return errors.problem(409, "Invoice is finalized", "Finalized invoices cannot be deleted.")
    del _INVOICES[invoice_id]
    log.info("invoice_deleted", invoice_id=invoice_id)
    return "", 204"
}

